function depart(s,truckId){const t=s.trucks.find(t=>t.id===truckId);if(!t||t.state==='DEPARTED'||t.loading||!t.dock)return false;const dock=s.docks.outbound.find(d=>d.id===t.dock);if(dock)dock.truck=null;for(const id of t.loaded){const o=s.orders.find(o=>o.id===id);o.state='SHIPPED';o.shippedAt=s.time}t.state='DEPARTED';event(s,'OUTBOUND',t.plate+' 출발 · '+t.loaded.length+'건 / R'+pad(t.route),t.id);t.dock=null;return true}
