function advance(s,seconds){if(!Number.isFinite(seconds)||seconds<0||seconds>86400)throw Error('잘못된 모의 시간');while(seconds>0){const dt=Math.min(seconds,1);step(s,dt);seconds-=dt}return s}
function metrics(s){return {orders:s.orders.length,active:s.orders.filter(o=>o.state!=='SHIPPED').length,shipped:s.orders.filter(o=>o.state==='SHIPPED').length,stockWait:s.orders.filter(o=>o.state==='WAIT_STOCK').length,inOccupied:s.docks.inbound.filter(d=>d.truck).length,outOccupied:s.docks.outbound.filter(d=>d.truck).length,robots:s.jobs.filter(j=>j.floor===4).length,ports:s.jobs.filter(j=>j.floor===4).length,picking:s.jobs.length,pickQueue:s.orders.reduce((n,o)=>n+o.lines.filter(l=>l.state==='QUEUED').length,0),inQueue:s.receipts.filter(r=>r.state==='WAIT_DOCK').length,outQueue:s.trucks.filter(t=>t.state==='WAIT_DOCK').length,putawayQty:s.receipts.filter(r=>r.state==='PUTAWAY').reduce((n,r)=>n+r.items.reduce((a,i)=>a+i.qty,0),0),stockQty:Object.values(s.stock).reduce((n,x)=>n+x.qty,0),reserved:Object.values(s.stock).reduce((n,x)=>n+x.reserved,0)}}
